//! Research: distill ordered, sight-filtered teacher demonstrations into navigator memory.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-teacher-task.rs"] mod task;
#[path = "../runs/quality-research/navigation-viewpoint-teacher.rs"] mod teacher;
use task::{Task,Route};
use flight_control::FlightPilot;
use bevy_gym::training::{RecurrentPpoAgent,RecurrentPpoPolicy,RecurrentPpoConfig,RecurrentBehaviorSample,SeedConfig,SplitMix64};
fn route(index:usize)->Route{if index%2==0{Route::House}else{Route::Pipe}}
fn collect(policy:Option<&RecurrentPpoPolicy>,pilot:&FlightPilot,course:Route,seed:u64)->Vec<RecurrentBehaviorSample>{
 let mut task=Task::new(seed,course);let mut teacher=teacher::Teacher::default();let mut memory=policy.map(RecurrentPpoPolicy::initial_memory);let mut samples=Vec::new();
 while !task.ended&&task.steps<3000{
  let observation=task.features();let target=teacher.action(&task);
  let action=if let Some(policy)=policy{let action=policy.mean_action(&observation,memory.as_ref().unwrap()).unwrap();memory=Some(action.next_memory);action.action}else{target.clone()};
  samples.push(RecurrentBehaviorSample{observation,action:target});task.advance(&action,pilot);
 }samples
}
fn evaluate(policy:&RecurrentPpoPolicy,pilot:&FlightPilot)->serde_json::Value{
 let mut rows=Vec::new();for course in [Route::House,Route::Pipe]{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,course);let mut memory=policy.initial_memory();let mut held=0;let mut seen=0;let mut tail=std::collections::VecDeque::new();
  while !task.ended&&task.steps<3000{let action=policy.mean_action(&task.features(),&memory).unwrap();memory=action.next_memory;task.advance(&action.action,pilot);let trace=task.trace();let visible=trace["visible"].as_bool().unwrap();tail.push_back(visible);if tail.len()>100{tail.pop_front();}if trace["hold"].as_u64().unwrap()>0{held+=1;if visible{seen+=1;}}}
  let mut result=task.result();result["seed"]=seed.into();result["hidden_samples"]=held.into();result["hidden_visible_samples"]=seen.into();result["last_100_visible"]=tail.iter().filter(|&&visible|visible).count().into();rows.push(result);
 }}serde_json::json!(rows)
}
#[test]
fn train_sequence_navigator(){
 let pilot=FlightPilot::bundled().unwrap();let config=RecurrentPpoConfig{actor_hidden_size:64,critic_hidden_sizes:vec![64,64],actor_learning_rate:0.0005,..Default::default()};
 let seeds=SeedConfig::from_root(43);let mut agent=RecurrentPpoAgent::load_actor_with_fresh_critic("docs/progress/drone-navigation-cover.mpk",32,32,1,&[-1.0;4],&[1.0;4],config,seeds).unwrap();let mut random=SplitMix64::new(0x53455155454e4345);
 let seed=|lane:usize,episode:u64|(seeds.environment_episode(lane,episode)&(u64::MAX>>1))|(1<<10);
 let mut episodes:[Vec<Vec<RecurrentBehaviorSample>>;2]=std::array::from_fn(|_|Vec::new());
 for (course,replay) in episodes.iter_mut().enumerate(){for episode in 0..10{replay.push(collect(None,&pilot,route(course),seed(course,episode)));}}
 std::fs::create_dir_all("runs/quality-research/navigation-sequence-imitation").unwrap();
 let initial=evaluate(&agent.policy(),&pilot);println!("INITIAL={initial}");std::fs::write("runs/quality-research/navigation-sequence-imitation/0.json",initial.to_string()).unwrap();
 for update in 1..=300{
  let mut losses=Vec::new();
  for replay in &episodes{
   let episode=&replay[(random.unit_f64()*replay.len() as f64) as usize];
   let start=match update%4{0=>0,1=>(random.unit_f64()*episode.len().min(150) as f64) as usize,2=>(random.unit_f64()*episode.len() as f64) as usize,_=>episode.len().saturating_sub(128)};let end=(start+128).min(episode.len());
   // Reconstruct current-policy memory from the exact demonstration prefix.
   let policy=agent.policy();let mut memory=policy.initial_memory();for sample in &episode[..start]{memory=policy.mean_action(&sample.observation,&memory).unwrap().next_memory;}
   losses.push(agent.behavior_clone_sequence(&episode[start..end],&memory).unwrap());
  }
  if update%10==0{let policy=agent.policy();for (course,replay) in episodes.iter_mut().enumerate(){replay.push(collect(Some(&policy),&pilot,route(course),seed(course,1000+update)));if replay.len()>14{replay.remove(10);}}}
  if update==1||update%20==0{let policy=agent.policy();let scores=evaluate(&policy,&pilot);println!("UPDATE={update} LOSSES={losses:?} SCORES={scores}");std::fs::write(format!("runs/quality-research/navigation-sequence-imitation/{update}.json"),scores.to_string()).unwrap();std::fs::write(format!("runs/quality-research/navigation-sequence-imitation/{update}.mpk"),policy.to_bytes().unwrap()).unwrap();}
 }
}

//! Experimental ten-hertz navigation task over the unchanged fifty-hertz flight pilot.
use super::{arena::{Arena,Movement,layout::Surface},sight::{Sight,Contact},flight_control::{FlightGoal,FlightPilot}};
use bevy::math::{Dir2,Dir3,Vec2,Vec3};
use bevy_gym::{Env,robots::{DroneHover,DroneObstacle,DroneObservation}};
use std::time::Duration;

#[derive(Clone,Copy,Debug)]
pub enum Route {Stationary,Lateral,Approach,House,Pipe}
pub struct Task {
 arena:Arena,drone:DroneHover,sight:Sight,previous_visible:Option<Vec3>,velocity:Vec3,
 route:Route,right:bool,back:bool,stage:usize,hold:u32,pub steps:u32,pub visible:u32,pub first_seen:Option<u32>,pub ended:bool,pub score:f32,
}
impl Task {
 pub fn new(seed:u64,route:Route)->Self {
  let arena=Arena::default();
  let obstacles=arena.blocks().iter().filter(|b|b.surface!=Surface::Floor).map(|b|DroneObstacle::try_from((b.centre,b.half,b.rotation)).unwrap());
  let mut drone=DroneHover::with_obstacles(obstacles);drone.reset(Some(seed));
  Self{arena,drone,sight:Sight::default(),previous_visible:None,velocity:Vec3::ZERO,route,right:true,back:false,stage:0,hold:0,steps:0,visible:0,first_seen:None,ended:false,score:0.0}
 }
 pub fn contact(&self)->Contact{self.sight.contact()}
 pub fn observation(&self)->DroneObservation{self.drone.observation()}
 fn rays(&self)->[(Vec3,f32);8]{
  let current=self.observation();let forward=current.orientation()*Vec3::NEG_Z;
  let forward=Vec3::new(forward.x,0.0,forward.z).normalize_or_zero();let right=Vec3::new(-forward.z,0.0,forward.x);
  std::array::from_fn(|index|{
   let angle=index as f32*std::f32::consts::TAU/8.0;let direction=right*angle.cos()+forward*angle.sin();
   let distance=[-0.4_f32,0.0,0.4].into_iter().map(|height|{let from=current.position()+Vec3::Y*height;self.arena.obstruction(from,from+direction*3.0).unwrap_or(3.0)}).fold(3.0_f32,f32::min);
   (direction,distance)
  })
 }
 pub fn features(&self)->Vec<f32>{
  let obs=self.observation();let inverse=obs.orientation().inverse();let body_velocity=inverse*obs.linear_velocity()/4.0;
  let gravity=inverse*Vec3::Y;let angular=obs.angular_velocity()/4.0;let forward=obs.orientation()*Vec3::NEG_Z;
  let mut input=vec![obs.position().y/3.0];input.extend(body_velocity.to_array());input.extend(gravity.to_array());input.extend(angular.to_array());input.extend([forward.x,forward.z,obs.position().x/10.0,obs.position().z/10.0]);
  let (point,flags,age)=match self.sight.contact(){Contact::Unknown=>(obs.position(),[1.0,0.0,0.0],0.0),Contact::Visible(p)=>(p,[0.0,1.0,0.0],0.0),Contact::Remembered{point,age}=>(point,[0.0,0.0,1.0],age.as_secs_f32()/3.0)};
  input.extend((inverse*(point-obs.position())/10.0).to_array());input.extend(flags);input.push(age);input.extend((inverse*self.velocity/4.0).to_array());input.extend(self.rays().map(|(_,range)|range/3.0));assert_eq!(input.len(),32);input
 }
 pub fn teacher(&self)->Vec<f32>{
  let obs=self.observation();let current=obs.position();let forward=obs.orientation()*Vec3::NEG_Z;
  let (position,yaw)=match self.sight.contact(){
   Contact::Unknown=>(Vec3::new(current.x,2.5,current.z),0.5),
   contact=>{
    let (point,age)=match contact{Contact::Visible(point)=>(point,0.0),Contact::Remembered{point,age}=>(point,age.as_secs_f32()),Contact::Unknown=>unreachable!()};
    let point=point+self.velocity*(age+0.5);let direction=Vec3::new(point.x-current.x,0.0,point.z-current.z).normalize_or_zero();
    (Vec3::new(point.x,2.5,point.z)-direction*5.0,forward.cross(direction).y.atan2(forward.dot(direction)))
   }
  };
  let mut displacement=(position-current).clamp_length_max(3.0);
  for (direction,distance) in self.rays(){if distance<2.0{displacement-=direction*(2.0-distance)*2.0;}}
  let body=obs.orientation().inverse()*displacement.clamp_length_max(3.0)/3.0;
  vec![body.x,body.y,body.z,yaw/std::f32::consts::PI]
 }
 pub fn goal_action(&self,position:Vec3,heading:Vec3)->Vec<f32>{
  let obs=self.observation();let displacement=(position-obs.position()).clamp_length_max(3.0);let body=obs.orientation().inverse()*displacement/3.0;let forward=obs.orientation()*Vec3::NEG_Z;let direction=heading.normalize();let yaw=forward.cross(direction).y.atan2(forward.dot(direction));vec![body.x,body.y,body.z,yaw/std::f32::consts::PI]
 }
 pub fn advance(&mut self,action:&[f32],pilot:&FlightPilot)->f32{
  assert!(!self.ended&&self.steps<3000);assert_eq!(action.len(),4);assert!(action.iter().all(|v|v.is_finite()&&(-1.0..=1.0).contains(v)));
  let obs=self.observation();let position=(obs.position()+obs.orientation()*Vec3::new(action[0],action[1],action[2])*3.0).clamp(Vec3::new(-9.5,1.0,-9.5),Vec3::new(9.5,4.0,9.5));
  let forward=bevy::math::Quat::from_rotation_y(action[3]*std::f32::consts::PI)*(obs.orientation()*Vec3::NEG_Z);let heading=Dir2::new(Vec2::new(forward.x,forward.z)).unwrap_or(Dir2::X);
  let goal=FlightGoal::try_from((position,heading)).unwrap();let mut reward=0.0;
  for _ in 0..5 {
   let character=self.arena.position();if character.x>6.0{self.right=false;}if character.x < -6.0{self.right=true;}if character.z<3.0{self.back=true;}if character.z>9.0{self.back=false;}
   let movement=if self.steps<250{Movement::Idle}else{match self.route{Route::Stationary=>Movement::Idle,Route::Lateral=>if self.right{Movement::Right}else{Movement::Left},Route::Approach=>if self.back{Movement::Backward}else{Movement::Forward},
     Route::House|Route::Pipe=>{
      let points=match self.route{Route::House=>[Vec3::new(0.0,0.0,-3.0),Vec3::new(-5.0,0.0,-3.0),Vec3::new(-5.0,0.0,-1.0),Vec3::new(-1.0,0.0,-3.0),Vec3::new(0.0,0.0,9.0)],_=>[Vec3::new(5.0,0.0,6.0),Vec3::new(5.0,0.0,1.0),Vec3::new(5.0,0.0,-4.0),Vec3::new(0.0,0.0,-4.0),Vec3::new(0.0,0.0,9.0)]};
      let current=self.arena.position();let delta=points[self.stage%5]-Vec3::new(current.x,0.0,current.z);
      if delta.length()<0.2{if self.stage%5==1{self.hold+=1;}else{self.stage+=1;self.hold=0;}Movement::Idle}else{Movement::from([delta.z < -0.12,delta.z>0.12,delta.x < -0.12,delta.x>0.12])}
     }}};self.arena.step(movement);
   let step=self.drone.step(pilot.action(self.observation(),goal).unwrap());self.steps+=1;self.ended=step.is_done();
   let obs=self.observation();let orientation=obs.orientation();let contact=self.sight.sample(&self.arena,obs.position()+orientation*Vec3::new(0.0,0.0,-0.22),Dir3::new(orientation*Vec3::NEG_Z).unwrap(),self.arena.position(),Duration::from_millis(20));
   if let Contact::Visible(point)=contact{
    if let Some(previous)=self.previous_visible{let delta=point-previous;self.velocity=(Vec3::new(delta.x,0.0,delta.z)/0.02).clamp_length_max(4.0);}
    self.previous_visible=Some(point);self.visible+=1;self.first_seen.get_or_insert(self.steps);
    let error=point.distance(obs.position())-5.0;reward+=(1.0/(1.0+error*error/9.0))/5.0;
   }else{self.previous_visible=None;}
   if matches!(contact,Contact::Unknown){self.velocity=Vec3::ZERO;}
   if self.ended{reward-=5.0;break;}
  }
  self.score+=reward;reward
 }
 pub fn trace(&self)->serde_json::Value{serde_json::json!({"time_seconds":self.steps as f32*0.02,"drone_metres":self.observation().position().to_array(),"target_metres":self.arena.position().to_array(),"visible":matches!(self.sight.contact(),Contact::Visible(_)),"stage":self.stage,"hold":self.hold})}
 pub fn result(&self)->serde_json::Value{serde_json::json!({"route":format!("{:?}",self.route),"steps":self.steps,"visible":self.visible,"first_seen":self.first_seen,"ended":self.ended,"score":self.score})}
}

//! A map-specific teacher chooses a route only after observing target movement.
use super::{sight::Contact,task::Task};
use bevy::math::Vec3;
/// The teacher stores its chosen route and advances only after reaching a waypoint.
#[derive(Clone,Copy,Debug,Default)]
enum Course { #[default] Observe, HouseCorner, HouseWindow, PipeApproach, PipeAcross, PipeEntrance }
/// This teacher reads filtered sight and its own pose. It does not read the target route.
#[derive(Default)]
pub struct Teacher { course:Course }
impl Teacher {
 pub fn action(&mut self,task:&Task)->Vec<f32>{
  if let Course::Observe=self.course {
   if let Contact::Visible(point)=task.contact(){
    if point.x>1.0&&point.z>4.5{self.course=Course::PipeApproach;}
    else if point.z<7.5&&point.x.abs()<1.0{self.course=Course::HouseCorner;}
   }
  }
  let position=task.observation().position();
  let (goal,heading)=match self.course {
   Course::Observe=>(Vec3::new(0.0,2.0,0.0),Vec3::Z),
   Course::HouseCorner=>(Vec3::new(-1.0,2.0,1.5),Vec3::NEG_Z),
   Course::HouseWindow=>(Vec3::new(-5.0,2.0,1.5),Vec3::NEG_Z),
   Course::PipeApproach=>(Vec3::new(0.0,2.0,8.0),Vec3::Z),
   Course::PipeAcross=>(Vec3::new(5.0,2.0,8.0),Vec3::NEG_Z),
   Course::PipeEntrance=>(Vec3::new(5.0,1.6,6.0),Vec3::NEG_Z),
  };
  let reached=match self.course{Course::PipeApproach=>position.z>=7.0&&position.x.abs()<1.5,_=>position.distance(goal)<0.25};
  if reached{self.course=match self.course {Course::HouseCorner=>Course::HouseWindow,Course::PipeApproach=>Course::PipeAcross,Course::PipeAcross=>Course::PipeEntrance,other=>other};}
  task.goal_action(goal,heading)
 }
}

